from __future__ import annotations
from .canonical import with_digest
def build_handoff(run:dict,decision:dict,report:dict,evidence:dict,budget:dict,events:dict,provenance:dict)->dict:
    body={'schema_version':'1.0.0','handoff_type':'ACL13_TO_ACL14','assessment_run_id':run['assessment_run_id'],'report_id':report['report_id'],'assessment_result':decision['decision'],'assessment_result_digest':decision['assessment_result_digest'],'report_digest':report['report_digest'],'evidence_bundle_digest':evidence['evidence_bundle_digest'],'budget_usage_digest':budget['budget_usage_digest'],'event_ledger_digest':events['ledger_digest'],'provenance_graph_digest':provenance['graph_digest'],'required_acl14_actions':['VERIFY_ONE_HOUR_ASSESSMENT_PACKAGE','AUTHOR_FIRST_REAL_CONTEXT_PILOT_CONTRACT','ISSUE_NON_CAPITAL_PILOT_READINESS_DECISION'],'forbidden_acl14_actions':['TREAT_TRIAGE_AS_VALIDATION','INVENT_PROSPECTIVE_EVIDENCE','REUSE_SYNTHETIC_DATA_AS_REAL_CONTEXT','AUTHORIZE_RUNTIME_OR_LIVE_ORDER','ACTIVATE_CAPITAL'],'first_real_context_pilot_design_allowed':decision['first_real_context_pilot_design_allowed'],'first_real_context_pilot_execution_allowed':False,'validation_claim_allowed':False,'alpha_claim_allowed':False,'production_security_ready':False,'runtime_activation_allowed':False,'live_order_submission_allowed':False,'capital_activation_allowed':False}
    return with_digest(body,'handoff_digest')
